html:
{% set approved_by_user = doc.ts_approved_by or "" %}
{% set is_ceo = frappe.db.get_value("Has Role", {"parent": approved_by_user, "role": "CEO"}, "name") if approved_by_user else "" %}
{% set is_md = frappe.db.get_value("Has Role", {"parent": approved_by_user, "role": "MD"}, "name") if approved_by_user else "" %}
{% set is_approved = doc.ts_approval_status == "Approved" and doc.docstatus == 1 %}
{% set has_terms = doc.tc_name or doc.terms or doc.ts_remark %}

<style>
@page { size: A4; margin: 6mm 10mm 6mm 10mm; }
body { font-family: Arial, sans-serif; font-size: 11px; color: #333; }
.po-header-img { width: 100%; max-height: 70px; }
.po-title { text-align: center; margin: 4px 0 1px; font-size: 15px; font-weight: bold; text-decoration: underline; letter-spacing: 1px; }
.po-subtitle { text-align: center; font-size: 8px; font-style: italic; color: #555; margin: 1px 0; }
.po-addr { text-align: center; font-size: 7px; color: #666; margin: 0; }
.po-info-table { width: 100%; border-collapse: collapse; margin: 4px 0; }
.po-info-table td { padding: 2px 5px; font-size: 10px; vertical-align: top; border: 1px solid #ddd; }
.po-info-label { font-weight: bold; width: 115px; }
.po-items { width: 100%; border-collapse: collapse; margin: 4px 0; }
.po-items th { border: 1px solid #333; padding: 3px 5px; font-size: 8px; text-transform: uppercase; text-align: center; font-weight: bold; }
.po-items td { border: 1px solid #ccc; padding: 2px 5px; font-size: 10px; }
.po-items .num { text-align: right; }
.po-items .ctr { text-align: center; }
.po-grand td { font-size: 12px; border-top: 2px solid #333; font-weight: bold; }
.po-terms-heading { font-size: 12px; font-weight: bold; text-decoration: underline; margin: 10px 0 4px; }
.po-terms-body { font-size: 10px; line-height: 1.6; }
.po-stamp-area { text-align: right; margin-top: 30px; padding-right: 20px; }
.po-stamp-img { width: 100px; height: auto; opacity: 0.85; }
.po-stamp-label { font-size: 10px; font-weight: bold; text-align: right; margin-top: 4px; padding-right: 25px; }
.po-footer { margin-top: 20px; border-top: 1px solid #ccc; padding-top: 8px; text-align: center; font-size: 8px; color: #555; }
.po-footer b { font-size: 9px; color: #333; }
.po-sig-line { border-top: 1px solid #333; width: 150px; margin: 40px 0 2px auto; }
.po-sig-label { text-align: right; font-size: 10px; font-weight: bold; }
.po-wrap { position: relative; }
.po-draft-watermark { position: absolute; top: 35%; left: 10%; font-size: 100px; color: rgba(255,0,0,0.08); font-weight: bold; -webkit-transform: rotate(-35deg); transform: rotate(-35deg); z-index: 0; letter-spacing: 20px; pointer-events: none; }
.po-payment-table { width: 100%; border-collapse: collapse; margin: 4px 0; }
.po-payment-table th { border: 1px solid #333; padding: 2px 5px; font-size: 8px; text-transform: uppercase; font-weight: bold; }
.po-payment-table td { border: 1px solid #ccc; padding: 2px 5px; font-size: 10px; }
.page-break { page-break-before: always; }
</style>

<div class="po-wrap">

<!-- HEADER IMAGE -->
<img src="/files/Header.png" class="po-header-img" onerror="this.style.display='none'">

<!-- TITLE -->
{% if not is_approved %}
<div style="text-align:center; font-size:13px; font-weight:bold; color:#cc0000; letter-spacing:2px; margin:3px 0 0;">DRAFT</div>
{% endif %}
<div class="po-title">PURCHASE ORDER</div>
<div class="po-subtitle">Kindly despatch your original documents to our office</div>
<div class="po-addr">Khasra No. 49/1, 49/2, 49/3, 509/1 &amp; 510/2, Khasara Road, Bodijunawani, Betul, Madhya Pradesh - 460001</div>
<div class="po-addr" style="margin-bottom:6px;">Email: purchase.catitions@betulbiofuel.com</div>

<!-- PO INFO -->
<table class="po-info-table">
<tr>
  <td class="po-info-label">Purchase Order #</td>
  <td><b>{{ doc.name }}</b></td>
  <td class="po-info-label">Date</td>
  <td>{{ frappe.format(doc.transaction_date, {"fieldtype": "Date"}) }}</td>
</tr>
<tr>
  <td class="po-info-label">Supplier</td>
  <td colspan="3"><b>{{ doc.supplier_name or doc.supplier }}</b></td>
</tr>
<tr>
  <td class="po-info-label">Address</td>
  <td>{% set addr = frappe.get_doc("Address", doc.supplier_address) if doc.supplier_address else none %}{% if addr %}{{ addr.address_line1 or "" }}{% if addr.address_line2 %}, {{ addr.address_line2 }}{% endif %}{% if addr.city %}, {{ addr.city }}{% endif %}{% if addr.state %}, {{ addr.state }}{% endif %} {{ addr.pincode or "" }}{% endif %}</td>
  <td class="po-info-label">Required By</td>
  <td>{{ frappe.format(doc.schedule_date, {"fieldtype": "Date"}) if doc.schedule_date else "" }}</td>
</tr>
<tr>
  <td class="po-info-label">Delivery Address</td>
  <td colspan="3">{% set del_addr = frappe.get_doc("Address", doc.shipping_address) if doc.shipping_address else none %}{% if del_addr %}{{ del_addr.address_line1 or "" }}{% if del_addr.city %}, {{ del_addr.city }}{% endif %}{% if del_addr.state %}, {{ del_addr.state }}{% endif %} {{ del_addr.pincode or "" }}{% else %}Khasara Road, Bodijunawani, Betul, Madhya Pradesh 460001{% endif %}</td>
</tr>
<tr>
  <td class="po-info-label">Contact</td>
  <td>{{ doc.contact_display or "" }}</td>
  <td class="po-info-label">Cost Center</td>
  <td>{{ doc.cost_center or "" }}</td>
</tr>
<tr>
  <td class="po-info-label">Project</td>
  <td>{{ doc.ts_project or doc.project or "" }}</td>
  <td class="po-info-label">Material Request</td>
  <td>{% set mr_ns = namespace(refs=[]) %}{% for item in doc.items %}{% if item.material_request and item.material_request not in mr_ns.refs %}{% set mr_ns.refs = mr_ns.refs + [item.material_request] %}{% endif %}{% endfor %}{{ mr_ns.refs | join(", ") }}</td>
</tr>
</table>

<!-- ITEMS TABLE -->
<table class="po-items">
<thead>
<tr>
  <th style="width:30px">S.No</th>
  <th>Item</th>
  <th style="width:65px">Quantity</th>
  <th style="width:50px">Unit</th>
  <th style="width:70px">Rate</th>
  <th style="width:50px">GST %</th>
  <th style="width:85px">Amount</th>
</tr>
</thead>
<tbody>
{% for item in doc.items %}
<tr>
  <td class="ctr">{{ loop.index }}</td>
  <td>{{ item.item_name or item.item_code }}{% if item.description %}<br><span style="font-size:8px;color:#888;">{{ item.description }}</span>{% endif %}</td>
  <td class="num">{{ frappe.format(item.qty, {"fieldtype": "Float", "precision": 2}) }}</td>
  <td class="ctr">{{ item.uom or item.stock_uom }}</td>
  <td class="num">{{ frappe.format(item.rate, {"fieldtype": "Currency"}) }}</td>
  <td class="ctr">{% if item.item_tax_template %}{% set _tpl = item.item_tax_template %}{% set _parts = _tpl.split('%') %}{% if _parts | length > 1 %}{% set _nums = _parts[0].replace('GST','').replace('-','').strip() %}{% if _nums %}{{ _nums }}{% else %}0{% endif %}{% else %}0{% endif %}{% elif doc.taxes %}{{ doc.taxes[0].rate }}{% endif %}</td>
  <td class="num">{{ frappe.format(item.amount, {"fieldtype": "Currency"}) }}</td>
</tr>
{% endfor %}
</tbody>
<tfoot>
<tr>
  <td colspan="6" class="num"><b>Net Total</b></td>
  <td class="num"><b>{{ frappe.format(doc.net_total, {"fieldtype": "Currency"}) }}</b></td>
</tr>
{% for tax in doc.taxes %}
<tr>
  <td colspan="6" class="num">{{ tax.description }}</td>
  <td class="num">{{ frappe.format(tax.tax_amount, {"fieldtype": "Currency"}) }}</td>
</tr>
{% endfor %}
{% if not doc.taxes %}
<tr>
  <td colspan="6" class="num">Total Taxes and Charges</td>
  <td class="num">{{ frappe.format(0, {"fieldtype": "Currency"}) }}</td>
</tr>
{% endif %}
<tr class="po-grand">
  <td colspan="6" class="num">Grand Total</td>
  <td class="num">{{ frappe.format(doc.grand_total, {"fieldtype": "Currency"}) }}</td>
</tr>
</tfoot>
</table>

<!-- PAYMENT TERMS -->
{% if doc.payment_schedule %}
<div style="font-size:10px; font-weight:bold; margin:4px 0 2px; text-decoration:underline;">Payment Terms</div>
<table class="po-payment-table">
<thead><tr><th>Due Date</th><th>Description</th><th>Invoice Portion</th><th>Amount Payable</th></tr></thead>
<tbody>
{% for ps in doc.payment_schedule %}
<tr>
  <td>{{ frappe.format(ps.due_date, {"fieldtype": "Date"}) }}</td>
  <td>{{ ps.payment_term or "" }}</td>
  <td class="num">{{ ps.invoice_portion }}%</td>
  <td class="num">{{ frappe.format(ps.payment_amount, {"fieldtype": "Currency"}) }}</td>
</tr>
{% endfor %}
</tbody>
</table>
{% endif %}

<!-- TERMS & REMARKS -->
{% if has_terms %}
{% if doc.tc_name or doc.terms %}
<div class="po-terms-heading">Terms and Conditions</div>
<div class="po-terms-body">{{ doc.terms or "" }}</div>
{% endif %}

{% if doc.ts_remark %}
<div class="po-terms-heading">Remarks</div>
<div class="po-terms-body">{{ doc.ts_remark }}</div>
{% endif %}
{% endif %}

<!-- STAMP / SIGNATURE -->
<div class="po-stamp-area">
{% if is_approved and is_ceo %}
  <img src="/files/CEO.jpeg" class="po-stamp-img">
  <div class="po-stamp-label">CEO</div>
{% elif is_approved and is_md %}
  <img src="/files/MD.jpeg" class="po-stamp-img">
  <div class="po-stamp-label">Managing Director</div>
{% else %}
  <div class="po-sig-line"></div>
  <div class="po-sig-label">Authority Signature</div>
{% endif %}
</div>

<!-- FOOTER -->
<div class="po-footer">
<b>AUTH. SIGNATORY</b><br>
<b>KINDLY DESPATCH YOUR ORIGINAL DOCUMENTS TO OUR OFFICE</b><br>
2nd Floor, LIC Building, Gurudwara Road, Betul, Ganj, Betul – 460001<br>
MOBILE NO. 7999844563 | E-mail: purchasemanager@betulbiofuel.com
</div>

</div><!-- /po-wrap -->
